.libPaths(c('work/stage5_Rlib',.libPaths()));library(susieR);library(coloc)
d<-read.csv('outputs/stage6_foxp2_pituitary_indel_analysis_input.csv');p<-nrow(d);stopifnot(p==1192,!anyDuplicated(d$rs));readR<-function(pop){R<-matrix(readBin(paste0('work/stage6_foxp2_pituitary_',pop,'_indel_ld.bin'),'double',n=p*p,size=8,endian='little'),p,p);dimnames(R)<-list(d$rs,d$rs);e<-eigen(R,symmetric=TRUE);stopifnot(min(e$values)>-1e-8);attr(R,'eigen')<-e;R};Rn<-readR('nfe');Rf<-readR('fin')
traits<-c('pituitary_FOXP2','MVP_insomnia','FinnGen_HFRS');ns<-c(237,253769,500737);zv<-list(d$qtl_z_anchor,d$mvp_z_anchor,d$hfrs_z_anchor);fits<-list();diagnostics<-list();membership<-list()
for(i in seq_along(traits)){z<-zv[[i]];names(z)<-d$rs;R<-if(traits[i]=='FinnGen_HFRS')Rf else Rn;lambda<-estimate_s_rss(z,R,n=ns[i]);set.seed(42);f<-susie_rss(z=z,R=R,n=ns[i],L=10,coverage=.95,estimate_residual_variance=FALSE,max_iter=500);fits[[traits[i]]]<-f;cs<-f$sets$cs;if(length(cs)>0)for(k in seq_along(cs)){ii<-cs[[k]];membership[[length(membership)+1]]<-data.frame(trait=traits[i],component=f$sets$cs_index[k],rs=d$rs[ii],pip=f$pip[ii])};diagnostics[[i]]<-data.frame(trait=traits[i],n_variants=p,working_n=ns[i],lambda=lambda,converged=f$converged,iterations=f$niter,n_sets=length(cs),max_pip=max(f$pip));cat(traits[i],lambda,length(cs),f$converged,'\n')}
write.csv(do.call(rbind,diagnostics),'outputs/stage6_foxp2_pituitary_indel_susie_diagnostics.csv',row.names=FALSE);if(length(membership))write.csv(do.call(rbind,membership),'outputs/stage6_foxp2_pituitary_indel_susie_members.csv',row.names=FALSE);saveRDS(fits,'work/stage6_foxp2_pituitary_indel_fits.rds')
pairs<-list();for(pair in list(c('pituitary_FOXP2','MVP_insomnia'),c('pituitary_FOXP2','FinnGen_HFRS'),c('MVP_insomnia','FinnGen_HFRS'))){a<-fits[[pair[1]]];b<-fits[[pair[2]]];if(length(a$sets$cs)==0||length(b$sets$cs)==0)next;for(p12 in c(1e-6,1e-5,5e-5)){z<-as.data.frame(coloc.susie(a,b,p1=1e-4,p2=1e-4,p12=p12)$summary);z$trait1<-pair[1];z$trait2<-pair[2];z$p12<-p12;pairs[[length(pairs)+1]]<-z}}
if(length(pairs))write.csv(do.call(rbind,pairs),'outputs/stage6_foxp2_pituitary_indel_coloc.csv',row.names=FALSE)
